import * as React from "react"

import { cn } from "@/lib/utils"
import { formatNumber } from "@/registry/dashboardcn/lib/format"

export interface MeterZone {
  label?: string
  from: number
  to: number
  /** Any CSS color. Defaults to chart-1. */
  color?: string
}

export interface SegmentedMeterProps extends React.ComponentProps<"div"> {
  value: number
  zones: MeterZone[]
  /** Only color the zone that contains the value; others stay muted. */
  highlightActive?: boolean
  /** Show zone boundary values under the bar. */
  showTicks?: boolean
  /** Show zone labels under the bar. */
  showLabels?: boolean
  /** Show a marker at the current value. */
  showMarker?: boolean
  tickFormatter?: (value: number) => string
}

function SegmentedMeter({
  value,
  zones,
  highlightActive = true,
  showTicks = true,
  showLabels = false,
  showMarker = true,
  tickFormatter = (v) => formatNumber(v),
  className,
  ...props
}: SegmentedMeterProps) {
  const min = Math.min(...zones.map((z) => z.from))
  const max = Math.max(...zones.map((z) => z.to))
  const span = max - min || 1
  const position = Math.min(1, Math.max(0, (value - min) / span))
  const activeIndex = zones.findIndex(
    (z, i) => value >= z.from && (value < z.to || (i === zones.length - 1 && value <= z.to))
  )

  return (
    <div
      data-slot="segmented-meter"
      role="meter"
      aria-valuemin={min}
      aria-valuemax={max}
      aria-valuenow={value}
      className={cn("flex flex-col gap-1.5", className)}
      {...props}
    >
      <div className="relative">
        <div className="flex h-2 w-full gap-0.5">
          {zones.map((zone, index) => {
            const active = index === activeIndex
            const color = zone.color ?? "var(--chart-1)"
            return (
              <div
                key={index}
                data-active={active}
                className="bg-muted h-full rounded-sm transition-colors first:rounded-l-full last:rounded-r-full"
                style={{
                  width: `${((zone.to - zone.from) / span) * 100}%`,
                  backgroundColor: !highlightActive || active ? color : undefined,
                }}
              />
            )
          })}
        </div>
        {showMarker ? (
          <div
            aria-hidden="true"
            className="bg-foreground ring-background absolute top-1/2 size-3 -translate-x-1/2 -translate-y-1/2 rounded-full ring-2"
            style={{ left: `${position * 100}%` }}
          />
        ) : null}
      </div>
      {showTicks || showLabels ? (
        <div className="text-muted-foreground relative h-4 text-[10px] tabular-nums">
          {showTicks
            ? [min, ...zones.map((z) => z.to)].map((tick, index, all) => (
                <span
                  key={index}
                  className={cn(
                    "absolute top-0",
                    index === 0 && "left-0",
                    index === all.length - 1 && "right-0",
                    index > 0 && index < all.length - 1 && "-translate-x-1/2"
                  )}
                  style={
                    index > 0 && index < all.length - 1
                      ? { left: `${((tick - min) / span) * 100}%` }
                      : undefined
                  }
                >
                  {tickFormatter(tick)}
                </span>
              ))
            : zones.map((zone, index) => (
                <span
                  key={index}
                  className="absolute top-0 -translate-x-1/2 truncate"
                  style={{
                    left: `${(((zone.from + zone.to) / 2 - min) / span) * 100}%`,
                  }}
                >
                  {zone.label}
                </span>
              ))}
        </div>
      ) : null}
    </div>
  )
}

export { SegmentedMeter }

export type NumberFormat = "number" | "compact" | "currency" | "percent"

export interface FormatNumberOptions {
  format?: NumberFormat
  /** ISO 4217 code, used when format is "currency". Defaults to USD. */
  currency?: string
  locale?: string
  maximumFractionDigits?: number
  /** Abbreviate large values, e.g. "$158K" instead of "$158,143". */
  compact?: boolean
}

const formatterCache = new Map<string, Intl.NumberFormat>()

function getFormatter(locale: string, options: Intl.NumberFormatOptions) {
  const key = locale + JSON.stringify(options)
  let formatter = formatterCache.get(key)
  if (!formatter) {
    formatter = new Intl.NumberFormat(locale, options)
    formatterCache.set(key, formatter)
  }
  return formatter
}

/**
 * Format a metric value for display.
 *
 * formatNumber(1234567)                          -> "1,234,567"
 * formatNumber(1234567, { format: "compact" })   -> "1.2M"
 * formatNumber(48.2, { format: "currency" })     -> "$48.20"
 * formatNumber(158143, { format: "currency", compact: true }) -> "$158K"
 * formatNumber(0.124, { format: "percent" })     -> "12.4%"
 */
export function formatNumber(
  value: number,
  {
    format = "number",
    currency = "USD",
    locale = "en-US",
    maximumFractionDigits,
    compact = false,
  }: FormatNumberOptions = {}
): string {
  if (!Number.isFinite(value)) return "—"

  // Compact values keep three significant digits: $158K, $1.23M, 41.2K.
  const compactOptions: Intl.NumberFormatOptions = compact
    ? maximumFractionDigits === undefined
      ? { notation: "compact", maximumSignificantDigits: 3 }
      : { notation: "compact", maximumFractionDigits }
    : {}
  switch (format) {
    case "compact":
      return getFormatter(locale, {
        notation: "compact",
        maximumFractionDigits: maximumFractionDigits ?? 1,
      }).format(value)
    case "currency":
      return getFormatter(locale, {
        style: "currency",
        currency,
        maximumFractionDigits: maximumFractionDigits ?? 2,
        ...compactOptions,
      }).format(value)
    case "percent":
      return getFormatter(locale, {
        style: "percent",
        maximumFractionDigits: maximumFractionDigits ?? 1,
      }).format(value)
    default:
      return getFormatter(locale, {
        maximumFractionDigits: maximumFractionDigits ?? 0,
        ...compactOptions,
      }).format(value)
  }
}

/**
 * Format a fractional change as a signed percentage.
 *
 * formatDelta(0.124)  -> "+12.4%"
 * formatDelta(-0.03)  -> "-3.0%"
 * formatDelta(0)      -> "0.0%"
 */
export function formatDelta(delta: number, locale = "en-US"): string {
  if (!Number.isFinite(delta)) return "—"
  return getFormatter(locale, {
    style: "percent",
    signDisplay: "exceptZero",
    maximumFractionDigits: 1,
    minimumFractionDigits: 1,
  }).format(delta)
}

/**
 * Fractional change between two values. Returns 0 when there is no baseline.
 */
export function computeDelta(current: number, previous: number): number {
  if (!previous) return 0
  return (current - previous) / Math.abs(previous)
}
